css:
#tongsci1-3-3-1-2-rate .rt-body { grid-template-columns: 1120px minmax(0, 1fr); }
#tongsci1-3-3-1-2-rate .rt-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; background: #f5f2ea; }
#tongsci1-3-3-1-2-rate .rt-stage canvas { touch-action: none; cursor: grab; user-select: none; -webkit-user-select: none; }
#tongsci1-3-3-1-2-rate .rt-panel { gap: 14px; }
#tongsci1-3-3-1-2-rate .rt-out { margin: 0; font-size: 21px; line-height: 1.55; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 10px 14px; min-height: 6.4em; flex: none; }
#tongsci1-3-3-1-2-rate .rt-out b { color: var(--accent); }
#tongsci1-3-3-1-2-rate .rt-def { margin: 0; display: grid; gap: 10px; flex: none; }
#tongsci1-3-3-1-2-rate .rt-def div { border-left: 6px solid #f2a53a; background: color-mix(in srgb, #f2a53a 10%, var(--paper-2)); border-radius: 0 10px 10px 0; padding: 8px 14px; }
#tongsci1-3-3-1-2-rate .rt-def dt { font: 800 20px var(--f-body); color: #a45d08; }
#tongsci1-3-3-1-2-rate .rt-def dd { margin: 2px 0 0; font-size: 19px; line-height: 1.5; }
section#tongsci1-3-3-1-2-rate.ex.u-done .rt-def { display: none; }

